// MiniMax-H3's three additions to the DiT set (h3/dit/gpu.go, VIDEO.md M7):
// the modulated RMS pre-norm with per-run AdaLN vectors, the q/k pack with
// H3's 96-channel rotate-half RoPE, and the bias copy that lands an input
// projection's rows in the residual stream.

//go:generate glslc --target-env=vulkan1.2 -O -I. -o h3_norm_mod.spv h3_norm_mod.comp
//go:generate glslc --target-env=vulkan1.2 -O -I. -o h3_bias_copy.spv h3_bias_copy.comp
//go:generate glslc --target-env=vulkan1.2 -O -I. -DTPW=8 -o h3_qk_pack_tpw8.spv h3_qk_pack.comp

//go:embed h3_norm_mod.spv
var H3NormMod []byte

//go:embed h3_bias_copy.spv
var H3BiasCopy []byte

//go:embed h3_qk_pack_tpw8.spv
var H3QKPackTPW8 []byte

// The attention screen's arms for MiniMax-H3's long key ranges (VIDEO.md
// M11): dit_attention_wmma.comp with fp16 context out, at more query tiles
// a wave (QT) and longer key blocks (KTIL) than the image DiT's QT=1 KTIL=4,
// Package shaders embeds pre-compiled SPIR-V binaries.
//
// Regenerate with `go generate ./...` after editing any .comp source
// (requires glslc, part of the Vulkan SDK / shaderc). Precision/tile-size
// variants of the same .comp source are generated via glslc -D flags rather
// than duplicating GLSL, and embedded under distinct names below.
package shaders

//go:generate glslc --target-env=vulkan1.2 -O -o double.spv double.comp

import _ "embed"

//go:embed double.spv
var Double []byte

// Bandwidth baseline.

//go:generate glslc --target-env=vulkan1.2 -O -o copy.spv copy.comp

//go:embed copy.spv
#version 450
// out[r] = in[r] + bias, row by row inside the fp32 activation arena
// (VIDEO.md M7): how an input projection's GEMM output, computed into scratch,
// reaches its rows of the residual stream with the checkpoint's fp32 bias
// added exactly. pc.aux2 = 0 is a plain copy.
#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    uint src = pc.inOff + r * pc.lda;
    uint dst = pc.outOff + r * pc.dim;
    for (uint c = gl_LocalInvocationID.x; c < pc.dim; c += 256u) {
        float v = act[src + c];
        if (pc.aux2 != 0u) {
            v += act[pc.aux0 + c];
        }
        act[dst + c] = v;
    }
}

