python3 - <<'EOF'
p='safetensors/safetensors.go'
s=open(p).read()
for sig,T in [('func (t *Tensor) F16(dst []uint16) ([]uint16, error) {\n','uint16'),('func (t *Tensor) F32(dst []float32) ([]float32, error) {\n','float32')]:
    assert s.count(sig)==1
    s=s.replace(sig, sig+'''	// The capacity is reserved once. Grown by append instead, a large slice
	// grows ~1.25x at a time, and a 3.1 GB table churned ~15 GB of copies
	// through the heap: enough, inside a server with a large live heap, to
	// wake the OOM killer before the GC's next target (VIDEO.md M11a).
	dst = slices.Grow(dst, t.Elems())
''')
if '"slices"' not in s:
    s=s.replace('import (\n','import (\n\t"slices"\n',1)
open(p,'w').write(s)
EOF
gofmt -w safetensors/safetensors.go && go vet ./safetensors && go test ./safetensors 2>&1 | tail -1 && go build -o ai ./cmd/serve && echo built

